#!/usr/bin/env python3
"""
lph.py - SL | Source Leak deobfuscator (Python only, single file)
No extra files needed: runtime data is prepared in .slcache on first run.

Usage (works from any folder):
    python lph.py <input> <output> [--timeout SECONDS]

Flow: full mode first -> falls back to fast mode automatically on failure.
"""
import os
import re
import shutil
import stat
import subprocess
import sys
import tempfile
import time

# ---- self-contained: the engine (core/ + runtime/) is packed inside this file ----
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = None
DEOB = None
BIN = None
SUPPORTED = (".lua", ".luau")


def log(msg):
    print(msg, flush=True)


def fix_bin_perms():
    """Panels often drop the exec bit on upload/unzip -> restore it."""
    if os.name == "nt":
        return
    for name in ("luau", "luau-ast"):
        p = os.path.join(BIN, name)
        if os.path.isfile(p):
            try:
                os.chmod(p, os.stat(p).st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
            except OSError:
                pass
        else:
            log(f"[!] Warning: {p} is missing")


# ---------------- AUTO-FIX (binary luau Linux + patch obfuscators) ----------------
PATCH_MARK = "def detect(source):"
PATCH_CODE = """


def by_name(name):
    for p in PLUGINS:
        if p.name == name:
            return p
    raise KeyError("unknown obfuscator %r" % name)


def detect(source):
    best, conf = PLUGINS[0], 0.0
    for p in PLUGINS:
        c = p.detect(source)
        if c > conf:
            best, conf = p, c
    return best, conf
"""


def _extract_bins(dest):
    import base64, io, lzma, tarfile
    os.makedirs(dest, exist_ok=True)
    import platform
    arch = platform.machine().lower()
    blob = LUAU_BLOB_ARM64 if arch in ("aarch64", "arm64", "armv8l", "armv8") else LUAU_BLOB_X64
    data = lzma.decompress(base64.b64decode(blob))
    with tarfile.open(fileobj=io.BytesIO(data)) as t:
        for m in t.getmembers():
            p = os.path.join(dest, m.name)
            if os.path.exists(p):
                os.remove(p)
            with open(p, "wb") as f:
                f.write(t.extractfile(m).read())
            os.chmod(p, 0o755)


def _luau_works(bin_dir):
    exe = os.path.join(bin_dir, "luau")
    try:
        tf = os.path.join(bin_dir, "_t.luau")
        with open(tf, "w") as f:
            f.write("print('ok')")
        r = subprocess.run([exe, tf], capture_output=True, timeout=20)
        os.remove(tf)
        return b"ok" in r.stdout
    except Exception:
        return False


def _patch_init(root):
    init = os.path.join(root, "core", "obfuscators", "__init__.py")
    with open(init, encoding="utf-8") as f:
        txt = f.read()
    if PATCH_MARK not in txt:
        with open(init, "a", encoding="utf-8") as f:
            f.write(PATCH_CODE)


DEVIRT_OLD = """        raise Unsupported("value %r in an expression" % (v,))

    def plain_closure"""
DEVIRT_NEW = """        if isinstance(v, LuaFunc):
            # [lph] VM-internal closure that can't be lifted: keep going with a
            # placeholder instead of aborting the rest of the function
            return Opaque("function", "function(...) --[[ SL: unrecoverable VM closure ]] end")
        raise Unsupported("value %r in an expression" % (v,))

    def plain_closure"""


def _patch_devirt(root):
    """Engine fix: one unliftable closure no longer truncates the whole output."""
    p = os.path.join(root, "core", "obfuscators", "luraph_v15", "devirt.py")
    with open(p, encoding="utf-8") as f:
        txt = f.read()
    if "[lph] VM-internal closure" in txt:
        return
    if DEVIRT_OLD not in txt:
        pass
        return
    with open(p, "w", encoding="utf-8") as f:
        f.write(txt.replace(DEVIRT_OLD, DEVIRT_NEW, 1))
    pass


def _extract_engine(root):
    import base64, io, lzma, tarfile
    for sub in ("core", "runtime"):
        p = os.path.join(root, sub)
        if os.path.isdir(p):
            shutil.rmtree(p, ignore_errors=True)
    os.makedirs(root, exist_ok=True)
    data = lzma.decompress(base64.b64decode(ENGINE_BLOB))
    with tarfile.open(fileobj=io.BytesIO(data)) as t:
        for m in t.getmembers():
            dest = os.path.join(root, m.name)
            if m.isdir():
                os.makedirs(dest, exist_ok=True)
            elif m.isfile():
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                with open(dest, "wb") as f:
                    f.write(t.extractfile(m).read())
    with open(os.path.join(root, ".engine_version"), "w") as f:
        f.write(ENGINE_VERSION)


def auto_fix():
    """Unpack the engine (once) into a writable + executable folder."""
    import platform
    global ROOT, DEOB, BIN
    cands = [os.path.join(HERE, ".slcache"),
             os.path.join(os.getcwd(), ".slcache"),
             os.path.join(os.path.expanduser("~"), ".slcache"),
             os.path.join(tempfile.gettempdir(), "slcache")]
    for root in cands:
        try:
            ver = os.path.join(root, ".engine_version")
            cur = open(ver).read().strip() if os.path.isfile(ver) else ""
            if cur != ENGINE_VERSION or not os.path.isfile(os.path.join(root, "core", "deob.py")):
                log("[*] preparing runtime (first run only) ...")
                _extract_engine(root)
            _patch_init(root)
            _patch_devirt(root)
            bin_dir = os.path.join(root, "bin")
            if os.name != "nt" and not _luau_works(bin_dir):
                log("[*] preparing runtime binaries ...")
                _extract_bins(bin_dir)
                if not _luau_works(bin_dir):
                    raise OSError("luau cannot be executed in " + bin_dir)
            ROOT, BIN = root, bin_dir
            DEOB = os.path.join(root, "core", "deob.py")
            return
        except Exception as e:
            log("[!] cache folder not usable, trying the next one ...")
    log("[x] No writable + executable folder found (the host blocks running binaries).")
    sys.exit(1)


def has_code(path):
    """True if the file contains real code, not just comments / blank lines."""
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            txt = f.read()
    except OSError:
        return False
    txt = re.sub(r"--\[(=*)\[.*?\]\1\]", "", txt, flags=re.S)
    txt = re.sub(r"--[^\n]*", "", txt)
    txt = re.sub(r'(?m)^\s*error\("devirt: [^\n]*$', "", txt)
    return txt.strip() != ""


def valid_output(path):
    try:
        with open(path, "rb") as f:
            return f.read().strip() != b""
    except OSError:
        return False


_ROUND_RE = re.compile(r"round (\d+): (\d+) functions")


def _relay(pipe):
    """Show only neutral progress lines from the worker; never its internals."""
    for raw in iter(pipe.readline, b""):
        line = raw.decode("utf-8", "replace").strip()
        m = _ROUND_RE.search(line)
        if m:
            log("[*] pass %s: %s functions recovered" % (m.group(1), m.group(2)))
        elif "run status:" in line:
            st = line.split("run status:", 1)[1].strip()
            st = "finished" if st.startswith("finished") else ("stopped in a loop (truncated)" if "loop" in st else "stopped early")
            log("[*] run: " + st)
    pipe.close()


def _deob_cmd(inp, out, extra):
    return [sys.executable, DEOB, inp, "-o", out, "--no-pypy"] + extra


def _env():
    env = os.environ.copy()
    env["PYTHONIOENCODING"] = "utf-8"
    return env


FULL_ARGS = ["--timeout", "90", "--budget", "15", "--max-runs", "4", "--devirt-rounds", "40"]
FAST_ARGS = ["--no-devirt", "--timeout", "30", "--budget", "10", "--max-runs", "4"]


def main():
    args = sys.argv[1:]
    timeout = 360   # default when --timeout is not given (or is invalid)
    for i, a in enumerate(list(args)):
        if a.startswith("--timeout"):
            val = a.split("=", 1)[1] if "=" in a else (args[i + 1] if i + 1 < len(args) else "")
            try:
                timeout = max(10, int(float(val)))
            except ValueError:
                log("[!] invalid --timeout value, using 360s")
                timeout = 360
            del args[i:i + (1 if "=" in a or not val else 2)]
            break
    if len(args) != 2:
        log("Usage: python lph.py <input> <output> [--timeout SECONDS]   (default 360)")
        return 2

    inp, out = os.path.abspath(args[0]), os.path.abspath(args[1])
    if not os.path.isfile(inp):
        log(f"[!] Input not found: {inp}")
        return 1
    os.makedirs(os.path.dirname(out) or ".", exist_ok=True)
    import platform
    log(f"[*] SL | Source Leak deobfuscator v12 | CPU: {platform.machine()}")
    auto_fix()

    tmpdir = tempfile.mkdtemp(prefix="lph_")
    base = os.path.splitext(os.path.basename(inp))[0] or "input"
    work_inp = os.path.join(tmpdir, base + ".lua")
    shutil.copyfile(inp, work_inp)
    full_out = os.path.join(tmpdir, "full.lua")
    fast_out = os.path.join(tmpdir, "fast.lua")
    cwd = os.path.join(ROOT, "core")
    start = time.time()
    try:
        log("=" * 50)
        log(f"[*] full mode (limit {timeout}s) + fast backup running ...")
        log("=" * 50)
        full = subprocess.Popen(_deob_cmd(work_inp, full_out, FULL_ARGS), cwd=cwd, env=_env(),
                                stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        import threading
        threading.Thread(target=_relay, args=(full.stdout,), daemon=True).start()
        fast = subprocess.Popen(_deob_cmd(work_inp, fast_out, FAST_ARGS), cwd=cwd, env=_env(),
                                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        timed_out = False
        try:
            full.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            timed_out = True
            full.kill()
            full.wait()
            log(f"\n[!] full mode hit the {timeout}s limit -> using the partial result")
        # the backup gets a short grace period if it is still running
        try:
            fast.wait(timeout=max(5, 45 - (time.time() - start)))
        except subprocess.TimeoutExpired:
            fast.kill()
            fast.wait()

        if not timed_out and full.returncode == 0 and has_code(full_out):
            shutil.copyfile(full_out, out)
            process_file(out)
            log(f"\n[+] SUCCESS (full) in {time.time() - start:.1f}s -> {out}")
            return 0
        if valid_output(fast_out) and (has_code(fast_out) or not valid_output(full_out)):
            shutil.copyfile(fast_out, out)
            with open(out, encoding="utf-8", errors="replace") as f:
                body = f.read()
            reason = "timed out" if timed_out else "failed"
            with open(out, "w", encoding="utf-8") as f:
                f.write("-- [SL] PARTIAL OUTPUT: full mode %s, this is the behaviour trace\n%s"
                        % (reason, body))
            process_file(out)
            log(f"\n[+] PARTIAL (fast) in {time.time() - start:.1f}s -> {out}")
            return 0
        if valid_output(full_out) or valid_output(fast_out):
            src = full_out if valid_output(full_out) else fast_out
            shutil.copyfile(src, out)
            with open(out, encoding="utf-8", errors="replace") as f:
                body = f.read()
            with open(out, "w", encoding="utf-8") as f:
                f.write("-- [SL] PARTIAL OUTPUT: no code could be recovered (layered / anti-tamper protected script)\n" + body)
            process_file(out)
            log(f"\n[!] PARTIAL: no code recovered (layered or anti-tamper protected) -> {out}")
            return 1
        # nothing usable: still write a file so the caller always gets an output
        with open(out, "w", encoding="utf-8") as f:
            f.write("-- [SL] deobfuscation failed: no output could be produced\n")
        process_file(out)
        log(f"\n[x] FAILED: no usable output (placeholder written to {out})")
        return 1
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)



# ================= OUTPUT PRETTIFIER + WATERMARK =================
import re
import math
WATERMARK = ("-- generated using SL | Source Leak\n"
             "-- https://discord.gg/x7YbZeezpm\n")

KEYWORDS = {"and", "break", "do", "else", "elseif", "end", "false", "for", "function",
            "if", "in", "local", "nil", "not", "or", "repeat", "return", "then", "true",
            "until", "while", "continue", "type", "export"}
# globals that are safe to inline (alias `local v2 = type` -> use `type`)
GLOBALS = {"type", "pcall", "xpcall", "error", "tostring", "tonumber", "ipairs", "pairs",
           "next", "select", "rawget", "rawset", "rawequal", "rawlen", "setmetatable",
           "getmetatable", "unpack", "assert", "print", "warn", "require", "loadstring",
           "getgenv", "getfenv", "setfenv", "getrenv", "getreg", "getgc", "identifyexecutor",
           "_G", "shared", "game", "workspace", "script", "string", "table", "math", "os",
           "bit32", "task", "buffer", "coroutine", "utf8", "debug", "Instance", "Vector3",
           "Vector2", "CFrame", "Color3", "UDim2", "UDim", "Enum", "tick", "time", "wait",
           "spawn", "delay", "typeof", "newproxy", "gcinfo", "collectgarbage", "syn",
           "request", "http_request", "hookfunction", "hookmetamethod", "newcclosure",
           "checkcaller", "getnamecallmethod", "setclipboard", "writefile", "readfile",
           "isfile", "makefolder", "isfolder", "delfile", "listfiles", "crypt", "Drawing",
           "firesignal", "fireclickdetector", "firetouchinterest", "getconnections",
           "cloneref", "gethui", "getcustomasset", "queue_on_teleport", "decompile"}
LIBS = {"string", "table", "math", "os", "bit32", "task", "buffer", "coroutine", "utf8", "debug"}

TOKEN_RE = re.compile(r"""
    (?P<ws>\s+)
  | (?P<comment>--\[(?P<ceq>=*)\[.*?\](?P=ceq)\]|--[^\n]*)
  | (?P<lstr>\[(?P<leq>=*)\[.*?\](?P=leq)\])
  | (?P<str>"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'|`(?:\\.|[^`\\])*`)
  | (?P<num>0[xX][0-9a-fA-F_]+|0[bB][01_]+|\d[\d_]*(?:\.[\d_]*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)
  | (?P<name>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<op>\.\.\.|\.\.=?|==|~=|<=|>=|//=?|::|[-+*/%^]=|->|.)
""", re.S | re.X)


def tokenize(src):
    toks = []
    pos = 0
    while pos < len(src):
        m = TOKEN_RE.match(src, pos)
        if not m:
            return None
        kind = m.lastgroup
        if kind in ("ceq", "leq"):
            kind = "comment" if m.group("comment") else "lstr"
        toks.append([kind, m.group(0)])
        pos = m.end()
    return toks


def analyze(toks):
    """name -> number of bindings (declarations + assignments)."""
    sig = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    binds = {}

    def add(n):
        binds[n] = binds.get(n, 0) + 1

    for k, i in enumerate(sig):
        kind, val = toks[i]
        prev = toks[sig[k - 1]][1] if k else ""
        if kind != "name" or val in KEYWORDS and val != "type":
            continue
        if prev in (".", ":"):
            continue
        # local a, b / for a, b / local function a / function a
        j = k - 1
        while j >= 1 and toks[sig[j]][1] == "," and toks[sig[j - 1]][0] == "name":
            j -= 2
        head = toks[sig[j]][1] if j >= 0 else ""
        if head in ("local", "for", "function"):
            add(val)
            continue
        # parameter: function(a, b)  /  function name(a, b)
        jj = k - 1
        while jj >= 0 and (toks[sig[jj]][1] == "," or
                           (toks[sig[jj]][0] == "name" and toks[sig[jj]][1] not in KEYWORDS)):
            jj -= 1
        if jj >= 0 and toks[sig[jj]][1] == "(":
            b = jj - 1
            while b >= 0 and (toks[sig[b]][0] == "name" and toks[sig[b]][1] != "function"
                              or toks[sig[b]][1] in (".", ":")):
                b -= 1
            if b >= 0 and toks[sig[b]][1] == "function":
                add(val)
                continue
        # assignment: a = ..., a, b = ..., a += ...
        f = k + 1
        while f + 1 < len(sig) and toks[sig[f]][1] == "," and toks[sig[f + 1]][0] == "name":
            f += 2
        if f < len(sig) and toks[sig[f]][1] in ("=", "+=", "-=", "*=", "/=", "..=", "%=", "^=", "//="):
            add(val)
    return binds


def names_in(toks):
    return {t[1] for t in toks if t[0] == "name"}


def rename(toks, mapping):
    sig_prev = ""
    for t in toks:
        if t[0] == "name" and t[1] in mapping and sig_prev not in (".", ":"):
            t[1] = mapping[t[1]]
        if t[0] not in ("ws", "comment"):
            sig_prev = t[1]


def prettify(src):
    toks = tokenize(src)
    if toks is None:
        return src
    binds = analyze(toks)
    used = names_in(toks)
    sig = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    mapping = {}

    for k in range(len(sig) - 3):
        a, b, c, d = (toks[sig[k + x]] for x in range(4))
        if a[1] != "local" or b[0] != "name" or c[1] != "=":
            continue
        var = b[1]
        if not re.fullmatch(r"v\d+", var) or var in mapping:
            continue
        nxt = toks[sig[k + 4]][1] if k + 4 < len(sig) else ""
        # 1) local vN = <global>   -> inline the global name
        if binds.get(var, 0) == 1 and d[0] == "name" and d[1] in GLOBALS and nxt not in (".", ":", "(", "[", ",", "{") \
                and binds.get(d[1], 0) == 0:
            mapping[var] = d[1]
            continue
        # 2) local vN = fn(string, {...})  -> string_lib
        if binds.get(var, 0) == 1 and d[0] == "name" and nxt == "(" and k + 5 < len(sig):
            lib = toks[sig[k + 5]][1]
            if lib in LIBS and toks[sig[k + 6]][1] == ",":
                new = lib + "_lib"
                n = 2
                while new in used or new in mapping.values():
                    new = "%s_lib%d" % (lib, n)
                    n += 1
                mapping[var] = new

    rename(toks, mapping)
    out = "".join(t[1] for t in toks)
    # `local type = type` left over from inlining -> remove
    out = re.sub(r"(?m)^[ \t]*local ([A-Za-z_]\w*) = \1[ \t]*\n", "", out)
    return out


# ================= LUARMOR STRING LAYER =================
_LM_ESC = {"n": 10, "t": 9, "r": 13, "a": 7, "b": 8, "f": 12, "v": 11, "\\": 92, '"': 34, "'": 39, "\n": 10}


def _lua_str_bytes(body):
    out = bytearray(); i = 0; raw = body.encode("utf-8")
    while i < len(raw):
        c = raw[i]
        if c != 92:
            out.append(c); i += 1; continue
        i += 1; e = chr(raw[i])
        if e.isdigit():
            j = i
            while j < len(raw) and j - i < 3 and chr(raw[j]).isdigit():
                j += 1
            out.append(int(raw[i:j]) & 255); i = j
        elif e == "x":
            out.append(int(raw[i + 1:i + 3], 16)); i += 3
        elif e == "u":
            j = raw.index(b"}", i)
            out += chr(int(raw[i + 2:j], 16)).encode("utf-8"); i = j + 1
        elif e == "z":
            i += 1
            while i < len(raw) and chr(raw[i]).isspace():
                i += 1
        else:
            out.append(_LM_ESC.get(e, ord(e))); i += 1
    return bytes(out)


def _lua_quote(b):
    s = ['"']
    for i, c in enumerate(b):
        if c == 34: s.append('\\"')
        elif c == 92: s.append("\\\\")
        elif c == 10: s.append("\\n")
        elif c == 9: s.append("\\t")
        elif 32 <= c < 127: s.append(chr(c))
        else:
            nxt = b[i + 1] if i + 1 < len(b) else 0
            s.append("\\%03d" % c if 48 <= nxt <= 57 else "\\%d" % c)
    return "".join(s) + '"'


def luarmor_strings(text):
    """Decrypt Luarmor's own string layer: CACHE[DEC("...", KEY)] -> "plain"."""
    m = re.search(r"n = \(n \* (\d+) \+ (\d+)\) % (\d+)\s+repeat\s+n2 = n2 \* (\d+) % (\d+)", text)
    if not m:
        return text
    mul, add, mod, m2, p2 = map(int, m.groups())
    sh = re.search(r"floor\(n / 2 \^ \((\d+) - \(n2 - n3\) / 32\)\)", text[m.end():m.end() + 400])
    shift = int(sh.group(1)) if sh else 13
    d = re.search(r"local function (\w+)\(arg, arg2\)(.{0,400}?)n = arg2 % (\d+)\s+n2 = arg2 % (\d+) \+ (\d+)"
                  r".{0,200}?local n3 = (\d+)", text, re.S)
    if not d:
        return text
    dec, kmod, a2, b2, seed = d.group(1), int(d.group(3)), int(d.group(4)), int(d.group(5)), int(d.group(6))

    def decrypt(data, key):
        st = {"n": key % kmod, "n2": key % a2 + b2, "q": []}

        def prng():
            if not st["q"]:
                st["n"] = (st["n"] * mul + add) % mod
                while True:
                    st["n2"] = st["n2"] * m2 % p2
                    if st["n2"] != 1:
                        break
                n2 = st["n2"]; n3 = n2 % 32
                n4 = math.floor(st["n"] / 2 ** (shift - (n2 - n3) / 32)) % 4294967296 / 2 ** n3
                n5 = math.floor(n4 % 1 * 4294967296) + math.floor(n4)
                n6 = n5 % 65536; n7 = (n5 - n6) / 65536; n8 = n6 % 256; n9 = n7 % 256
                st["q"] = [n8, (n6 - n8) / 256, n9, (n7 - n9) / 256]
            return int(st["q"].pop())
        out = bytearray(); acc = seed
        for c in data:
            acc = (c + prng() + acc) % 256
            out.append(acc)
        return bytes(out)

    pat = re.compile(r"\b\w+\[" + re.escape(dec) + r'\("((?:[^"\\]|\\.)*)", (\d+)\)\]', re.S)
    cnt = [0]

    def rep(mm):
        try:
            cnt[0] += 1
            q = _lua_quote(decrypt(_lua_str_bytes(mm.group(1)), int(mm.group(2))))
            nxt = mm.string[mm.end():mm.end() + 1]
            return "(" + q + ")" if nxt in (":", ".", "[", "(") else q
        except Exception:
            return mm.group(0)
    text = pat.sub(rep, text)
    # X["name"] -> X.name, X:["m"] stays
    text = re.sub(r'(\w|\]|\))\["([A-Za-z_][A-Za-z0-9_]*)"\]',
                  lambda mm: mm.group(0) if mm.group(2) in KEYWORDS else "%s.%s" % (mm.group(1), mm.group(2)), text)
    return text


def collapse_tables(text):
    """local t = {} + t[1] = a / t[2] = b / t.X = c (consecutive lines) -> one table literal."""
    lines = text.split("\n")
    out = []
    i = 0
    hdr = re.compile(r"^(\s*)local (\w+) = \{\}\s*$")
    while i < len(lines):
        m = hdr.match(lines[i])
        if not m:
            out.append(lines[i]); i += 1; continue
        ind, name = m.group(1), m.group(2)
        items = []
        j = i + 1
        nxt = 1
        ref = re.compile(r"\b" + re.escape(name) + r"\b")
        pre = []
        while j < len(lines) and re.match("^" + re.escape(ind) + r"local [\w, ]+ = [^\n]*$", lines[j]) \
                and not ref.search(lines[j]) and len(pre) < 12:
            v = re.sub(r'"(?:[^"\\]|\\.)*"', '""', lines[j])
            if not all(v.count(o) == v.count(c) for o, c in ("()", "{}", "[]")) or "function" in v:
                break
            pre.append(lines[j]); j += 1
        def balanced(v):
            v = re.sub(r'"(?:[^"\\]|\\.)*"|\'(?:[^\'\\]|\\.)*\'', '""', v)
            if "[[" in v or "--" in v:
                return False
            return all(v.count(o) == v.count(c) for o, c in ("()", "{}", "[]"))
        while j < len(lines):
            L = lines[j]
            a = re.match(r"^" + re.escape(ind) + re.escape(name) + r"\[(\d+)\] = (.+)$", L)
            b = re.match(r"^" + re.escape(ind) + re.escape(name) + r"\.([A-Za-z_]\w*) = (.+)$", L)
            if a and balanced(a.group(2)) and int(a.group(1)) == nxt and not ref.search(a.group(2)) and not a.group(2).rstrip().endswith(("function(", "{", "(")):
                items.append((None, a.group(2).rstrip())); nxt += 1
            elif b and balanced(b.group(2)) and not ref.search(b.group(2)) and b.group(1) not in KEYWORDS and not b.group(2).rstrip().endswith(("function(", "{", "(")) \
                    and not re.search(r"\bfunction\b", b.group(2)):
                items.append((b.group(1), b.group(2).rstrip()))
            else:
                break
            j += 1
        if len(items) < 2:
            out.append(lines[i]); i += 1; continue
        out.extend(pre)
        parts = [v if k is None else "%s = %s" % (k, v) for k, v in items]
        one = "%slocal %s = { %s }" % (ind, name, ", ".join(parts))
        if len(one) <= 110:
            out.append(one)
        else:
            out.append("%slocal %s = {" % (ind, name))
            for p in parts:
                out.append("%s\t%s," % (ind, p))
            out.append("%s}" % ind)
        i = j
    return "\n".join(out)


def inline_consts(text):
    """local str53 = "CoreGui" used 1-3 times, never reassigned -> put the literal at the use."""
    decl = re.compile(r'(?m)^[ \t]*local ([A-Za-z_]\w*) = ("(?:[^"\\\n]|\\.){0,60}"|-?\d+(?:\.\d+)?)[ \t]*\n')
    cands = {}
    for m in decl.finditer(text):
        cands.setdefault(m.group(1), []).append(m)
    for name, ms in cands.items():
        if len(ms) != 1 or name in KEYWORDS:
            continue
        m = re.search(r'(?m)^[ \t]*local ' + re.escape(name) + r' = ("(?:[^"\\\n]|\\.){0,60}"|-?\d+(?:\.\d+)?)[ \t]*\n', text)
        if not m:
            continue
        lit = m.group(1)
        rest = text[:m.start()] + text[m.end():]
        occ = list(re.finditer(r"(?<![\w.:])" + re.escape(name) + r"\b", rest))
        if not 1 <= len(occ) <= 3:
            continue
        bad = False
        for o in occ:
            after = rest[o.end():o.end() + 4]
            before = rest[max(0, o.start() - 7):o.start()]
            if re.match(r"\s*(=[^=]|\+=|-=|\*=|/=|\.\.=|,)", after) or before.rstrip().endswith(("local", "for", "function")) \
                    or re.search(r"\bfunction\s*\w*\([^)]*$", rest[max(0, o.start() - 80):o.start()]):
                bad = True; break
        if bad:
            continue
        # every use must come after the declaration
        if occ[0].start() < m.start():
            continue

        def rep(o):
            nxt = o.string[o.end():o.end() + 1]
            return "(" + lit + ")" if nxt in (":", ".", "[", "(") or (lit.startswith("-") and o.string[o.start() - 2:o.start()] in ("- ", "^ ")) else lit
        text = re.sub(r"(?<![\w.:])" + re.escape(name) + r"\b", rep, rest)
    return text


def _sim_note(m):
    msg = re.sub(r'^(?:(?:LPH|Script|\[string "[^"]*"\]):\d+:\s*)+', '', m.group(2).strip())
    kinds = [
        ("call a nil value", "calls a function the simulator does not provide"),
        ("compare", "compares a number with an object the simulator only fakes"),
        ("index function with", "uses an API result the simulator returns in a different form"),
        ("index nil", "reads a value the simulator does not provide"),
        ("table index is nil", "uses a key the simulator could not produce"),
        ("invalid argument", "passes a fake object to a built-in function"),
        ("arithmetic", "does math on a value the simulator only fakes"),
    ]
    why = next((w for k, w in kinds if k in msg), "hit something the simulator cannot reproduce")
    return "%s-- [SL] note: the simulated run stopped in this branch (the script %s). " \
           "Code above is valid; the rest of this branch was not traced." % (m.group(1), why)


_SANITIZE = [
    (r"(?m)^([ \t]*)--\s*\[envlog\]\s*error:\s*(.*)$", _sim_note),
    (r"--\s*\[envlog\]\s*", "-- [SL] "),
    (r"--\s*\[deobf\]\s*", "-- [SL] "),
    (r"--\s*Luraph runtime function \(from the VM object, not part of the script: not lifted\)\.", "-- [SL] protected runtime function (cannot be recovered)."),
    (r"--\s*LPH_ENCFUNC decrypts a function this way: \(key, encrypted buffer, \.\.\.\) -> function\.", "-- [SL] decrypts an encrypted function: (key, buffer, ...) -> function."),
    (r'error\("Luraph runtime function, not devirtualized"\)', 'error("SL: protected function")'),
    (r'error\("devirt: [^"\n]*"\)', 'error("SL: this block could not be recovered")'),
    (r"\bluraph_runtime(\d+)\b", r"protected_fn\1"),
    (r"the engine failed to devirtualize this part", "this part could not be recovered"),
    (r"devirtualiz\w*", "recover"),
    (r"--\[\[ the caller's registers \]\]", ""),
]


def sanitize(text):
    for a, b in _SANITIZE:
        text = re.sub(a, b, text)
    return text


def strip_comments(text):
    """Remove every comment the tools added (watermarks are inserted afterwards)."""
    text = re.sub(r"(?m)^[ \t]*--\[(=*)\[.*?\]\1\][ \t]*\n", "", text, flags=re.S)
    text = re.sub(r"--\[(=*)\[(?:(?!\n).)*?\]\1\]", "", text)
    out = []
    for line in text.split("\n"):
        st = line.strip()
        if st.startswith("--"):
            continue
        k = line.find("--")
        if k > 0:
            pre = line[:k]
            if pre.count('"') % 2 == 0 and pre.count("'") % 2 == 0 and "[[" not in pre and "[=" not in pre:
                line = pre.rstrip()
        out.append(line)
    return "\n".join(out)


def finalize(text):
    text = sanitize(text)
    text = luarmor_strings(text)
    try:
        text = collapse_tables(inline_consts(text))
    except Exception:
        pass
    # engine artefact: `local ... = ...` is not valid Luau and is a no-op -> drop it
    text = re.sub(r"(?m)^[ \t]*local \.\.\. = \.\.\.[ \t]*\n", "", text)
    # a statement starting with "(" is ambiguous after a call -> end the previous line with ";"
    _ls = text.split("\n")
    for _i, _l in enumerate(_ls):
        if re.match(r"[ \t]*\([^\n]*\)[.:\[(]", _l):
            _j = _i - 1
            while _j >= 0 and not _ls[_j].strip():
                _j -= 1
            if _j >= 0:
                _p = _ls[_j].rstrip()
                if re.search(r"[\w)\]\"'}]$", _p) and not re.search(
                        r"(^|\W)(then|do|else|repeat|return|and|or|not|in|local|function)$", _p) \
                        and not _p.lstrip().startswith("--"):
                    _ls[_j] = _p + ";"
    text = "\n".join(_ls)
    text = re.sub(r"(?m)^(\s*for [^\n]*? in [A-Za-z_][\w.]*), nil, nil do$", r"\1 do", text)
    # blocks the engine failed to lift -> comment (instead of a crashing error())
    text = re.sub(r'(?m)^([ \t]*)error\("devirt: [^\n]*"\)[ \t]*$',
                  r'\1-- [SL] the engine failed to devirtualize this part (code after this point could not be recovered)',
                  text)
    try:
        text = prettify(text)
    except Exception:
        pass
    try:
        text = smart_rename(text)
    except Exception:
        pass
    lines = [l.rstrip() for l in text.replace("\r\n", "\n").split("\n")]
    # drop the deobfuscator's status comments at the top of the file
    while lines and (not lines[0].strip() or re.match(r"--\s*(run status|\d+ statements recorded|\[deobf\])", lines[0])):
        lines.pop(0)
    text = re.sub(r"\n{3,}", "\n\n", "\n".join(lines)).strip("\n")
    try:
        text = strip_comments(text)
        text = re.sub(r"\n{3,}", "\n\n", text).strip("\n")
    except Exception:
        pass
    try:
        text = scatter_watermarks(text)
        text = footer_watermark(text)
    except Exception:
        text += "\n"
    return WATERMARK + "\n" + text


def process_file(path):
    with open(path, encoding="utf-8", errors="replace") as f:
        text = f.read()
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(finalize(text))


# ===================== SCOPE-AWARE SMART RENAMER =====================
TARGET_RE = re.compile(r"(v\d+|tbl\d+|fn\d*|arg\d*|value\d*)$")
ASSIGN_OPS = ("=", "+=", "-=", "*=", "/=", "..=", "%=", "^=", "//=")
WORD_HINTS = [  # (regex over initializer text, name)
    (r"^\s*\w+\.create\(", "arr"), (r"^\s*table\.create\(", "arr"),
    (r"^\s*\w+\.clock\(\)", "startTime"), (r"^\s*\w+\.time\(\)", "timestamp"),
    (r"^\s*tick\(\)", "startTime"), (r"^\s*\w+\.gsub\(", "cleaned"),
    (r"^\s*\w+\.sub\(", "substr"), (r"^\s*\w+\.format\(", "formatted"),
    (r"^\s*\w+\.concat\(", "joined"), (r"^\s*\w+\.lower\(", "lowered"),
    (r"^\s*\w+\.upper\(", "uppered"), (r"^\s*\w+\.match\(", "matched"),
    (r"^\s*\w+\.find\(", "foundAt"), (r"^\s*\w+\.byte\(", "byte"),
    (r"^\s*\w+\.char\(", "char"), (r"^\s*\w+\.rep\(", "repeated"),
    (r"^\s*\w+\.floor\(", "floored"), (r"^\s*\w+\.ceil\(", "ceiled"),
    (r"^\s*\w+\.max\(", "maxValue"), (r"^\s*\w+\.min\(", "minValue"),
    (r"^\s*\w+\.bxor\(", "xored"), (r"^\s*\w+\.pack\(", "packed"),
    (r"^\s*\w+\.unpack\(", "unpacked"), (r"^\s*tostring\(", "str"),
    (r"^\s*tonumber\(", "num"), (r"^\s*#", "len"), (r"^\s*nil\s*$", "value"),
    (r"^\s*\{", "tbl"), (r"^\s*\"", "str"), (r"^\s*-?\d", "num"),
    (r"^\s*(true|false)\s*$", "flag"), (r"^\s*function\b", "func"),
    (r"^\s*require\(", "module"), (r"^\s*Instance\.new\(\"(\w+)\"", None),
    (r"^\s*\w+\s*\.\.", "str"), (r"^\s*sha\d+\(", "hash"),
    (r"^\s*\w*[Dd]ecode\w*\(", "decoded"), (r"^\s*\w*[Ee]ncode\w*\(", "encoded"),
    (r"^\s*\w+\[1\]\s*$", "first"), (r"^\s*\w+\[2\]\s*$", "second"),
    (r"^\s*\w+\[3\]\s*$", "third"), (r"^\s*\w+\[[^\]]+\]\s*$", "entry"),
    (r"^\s*\w+\(\)\s*$", "result"),
]


def _camel(s):
    parts = re.findall(r"[A-Za-z0-9]+", s)
    if not parts:
        return None
    out = parts[0][0].lower() + parts[0][1:] + "".join(p[:1].upper() + p[1:] for p in parts[1:])
    if not re.match(r"[A-Za-z_]", out):
        out = "_" + out
    return out[:24] if out not in KEYWORDS else out + "Value"


def _name_from_init(init):
    """Guess a name from the initializer expression text (single variable)."""
    init = init.strip()
    m = re.match(r"^\w+\((string|table|math|os|bit32|task|buffer|coroutine|utf8|debug),", init)
    if m:
        return m.group(1) + "_lib"
    m = re.match(r'^\w+\(\s*[\w.]+\s*,\s*"([A-Za-z_][\w ]{0,30})"\s*\)\s*$', init)  # fn8(syn, "crypt")
    if m:
        return _camel(m.group(1))
    m = re.match(r'^\w+\(\s*"([A-Za-z_][\w ]{0,30})"\s*\)\s*$', init)  # fn9("syn")
    if m:
        return _camel(m.group(1))
    m = re.match(r'^Instance\.new\("(\w+)"', init)
    if m:
        return _camel(m.group(1))
    m = re.match(r'^[\w.]+\.(\w+)\s*$', init)  # a.b.CreatorType
    if m:
        return _camel(m.group(1))
    m = re.match(r'^[\w.]+\[\s*"(\w+)"\s*\]\s*$', init)
    if m:
        return _camel(m.group(1))
    m = re.match(r'^\w+\(\s*[\w.]+\.(\w+)\s*[,)]', init)  # fn6(v.CreatorType, 32)
    if m and m.group(1)[0].isupper():
        return _camel(m.group(1))
    m = re.match(r'^(?:get|Get|fetch|Fetch|read|Read|load|Load|create|Create|make|Make|build|Build)([A-Z]\w*)\(', init)
    if m:
        return _camel(m.group(1))
    for rx, nm in WORD_HINTS:
        if re.search(rx, init):
            if nm:
                return nm
    return None


def _multi_names(init, count):
    init = init.strip()
    if re.match(r"^x?pcall\(", init):
        base = ["ok", "result", "result2", "result3"]
        return base[:count]
    return None


class _Decl:
    __slots__ = ("old", "new", "kind", "hint", "idx")

    def __init__(self, old, kind, idx):
        self.old, self.kind, self.idx = old, kind, idx
        self.new, self.hint = None, None


def smart_rename(src):
    toks = tokenize(src)
    if toks is None:
        return src
    sig = [i for i, t in enumerate(toks) if t[0] not in ("ws", "comment")]
    S = [toks[i] for i in sig]
    n = len(S)
    used = {t[1] for t in S if t[0] == "name"}

    scopes = [{}]          # stack of dict name->decl
    block_kinds = []       # parallel stack: block kinds
    pending = []           # (decls, bracket_depth, block_depth) activated after the statement
    ref = {}               # index sig -> decl
    decls = []
    bdepth = 0             # () [] {}
    brace_stack = []

    def lookup(name):
        for sc in reversed(scopes):
            if name in sc:
                return sc[name]
        return None

    def open_block(kind):
        scopes.append({})
        block_kinds.append(kind)

    def close_block():
        if len(scopes) > 1:
            scopes.pop()
            block_kinds.pop()

    def flush_pending(force=False):
        keep = []
        for ds, bd, kd in pending:
            if kd > len(block_kinds):
                continue                      # belongs to an already closed block
            if (force and kd == len(block_kinds)) or (bd == bdepth and kd == len(block_kinds)):
                for d in ds:
                    scopes[-1][d.old] = d
            else:
                keep.append((ds, bd, kd))
        pending[:] = keep

    def newline_between(a, b):
        # is there a newline between sig tokens a and b?
        for i in range(sig[a] + 1, sig[b]):
            if "\n" in toks[i][1]:
                return True
        return False

    fstack = []            # open function records
    frecs = []             # all function records
    for_header = None      # decls waiting for `do`
    func_params = None     # decls waiting for the closing `)` of params
    k = 0
    while k < n:
        kind, val = S[k]
        if k > 0 and pending and newline_between(k - 1, k):
            flush_pending()
        if until_close_pending_check(block_kinds) and False:
            pass
        prev = S[k - 1][1] if k else ""

        if kind == "name" and val == "local" and k + 1 < n:
            if S[k + 1][1] == "function" and k + 2 < n and S[k + 2][0] == "name":
                d = _Decl(S[k + 2][1], "func", k + 2)
                decls.append(d)
                scopes[-1][d.old] = d
                ref[k + 2] = d
                k += 3
                continue
            # local a, b = ...
            j = k + 1
            ds = []
            while j < n and S[j][0] == "name":
                d = _Decl(S[j][1], "local", j)
                ds.append(d)
                decls.append(d)
                ref[j] = d
                j += 1
                if j < n and S[j][1] == ":":        # type annotation: skip simple types
                    j += 2
                if j < n and S[j][1] == ",":
                    j += 1
                else:
                    break
            if j < n and S[j][1] == "=":
                # initializer hint (text up to newline at same depth)
                txt = []
                e = j + 1
                depth = 0
                while e < n:
                    if depth == 0 and e > j + 1 and newline_between(e - 1, e):
                        break
                    if S[e][1] in ("(", "[", "{"):
                        depth += 1
                    elif S[e][1] in (")", "]", "}"):
                        depth -= 1
                    txt.append(S[e][1])
                    e += 1
                init = " ".join(txt)
                init = re.sub(r"\s*([().,\[\]:#])\s*", r"\1", init).replace(",", ", ")
                if len(ds) == 1:
                    ds[0].hint = _name_from_init(init)
                else:
                    mn = _multi_names(init, len(ds))
                    if mn:
                        for d, h in zip(ds, mn):
                            d.hint = h
                pending.append((ds, bdepth, len(block_kinds)))
            else:
                for d in ds:
                    scopes[-1][d.old] = d
            k = j
            continue

        if kind == "name" and val == "function":
            # function a.b:c(params) / function(params)
            j = k + 1
            if j < n and S[j][0] == "name":   # global/field function name -> resolve first name
                d = lookup(S[j][1])
                if d:
                    ref[j] = d
                j += 1
                while j + 1 < n and S[j][1] in (".", ":"):
                    j += 2
            open_block("function")
            rec = {"start": k, "end": n, "params": [], "depth": len(block_kinds),
                   "ctx": [S[x][1] for x in range(max(0, k - 6), k)]}
            fstack.append(rec)
            frecs.append(rec)
            if j < n and S[j][1] == "(":
                j += 1
                while j < n and S[j][1] != ")":
                    if S[j][0] == "name":
                        d = _Decl(S[j][1], "param", j)
                        rec["params"].append(d)
                        decls.append(d)
                        scopes[-1][d.old] = d
                        ref[j] = d
                        if j + 1 < n and S[j + 1][1] == ":":
                            j += 2
                    j += 1
                k = j + 1
                continue
            k = j
            continue

        if kind == "name" and val == "for":
            open_block("for")
            j = k + 1
            ds = []
            while j < n and S[j][0] == "name":
                d = _Decl(S[j][1], "for", j)
                ds.append(d)
                decls.append(d)
                ref[j] = d
                j += 1
                if j < n and S[j][1] == ",":
                    j += 1
                else:
                    break
            # hint: for _, v in ipairs(x) -> item ; pairs -> key,value
            if j < n and S[j][1] == "in" and len(ds) >= 2:
                ds[0].hint = ds[0].hint or "key"
                ds[1].hint = "item" if (j + 1 < n and S[j + 1][1] == "ipairs") else "value"
            elif len(ds) == 1 and j < n and S[j][1] == "in":
                ds[0].hint = "item"
            if len(ds) >= 2 and j < n and S[j][1] == "in":
                e = j + 1
                if e + 1 < n and S[e][1] in ("pairs", "ipairs") and S[e + 1][1] == "(":
                    e += 2
                last = None
                while e < n and (S[e][0] == "name" or S[e][1] in (".", ":")) and S[e][1] not in ("do",):
                    if S[e][0] == "name":
                        last = S[e][1]
                    e += 1
                if last and len(last) > 3 and last.endswith("s") and not last.endswith("ss") \
                        and last not in ("pairs", "ipairs"):
                    sing = last[:-3] + "y" if last.endswith("ies") else last[:-1]
                    nm = _camel(sing)
                    if nm and nm not in KEYWORDS:
                        ds[1].hint = nm
            for_header = ds
            k = j
            continue

        if kind == "name" and val == "do":
            if for_header is not None:
                for d in for_header:
                    scopes[-1][d.old] = d
                for_header = None
            elif block_kinds and block_kinds[-1] == "while_head":
                block_kinds[-1] = "while"
            else:
                open_block("do")
            k += 1
            continue
        if kind == "name" and val == "while":
            open_block("while_head")
            k += 1
            continue
        if kind == "name" and val == "then":
            open_block("then")
            k += 1
            continue
        if kind == "name" and val in ("elseif", "else"):
            flush_pending(force=True)
            close_block()
            if val == "else":
                open_block("then")
            k += 1
            continue
        if kind == "name" and val == "repeat":
            open_block("repeat")
            k += 1
            continue
        if kind == "name" and val == "end":
            flush_pending(force=True)
            if fstack and fstack[-1]["depth"] == len(block_kinds) and block_kinds \
                    and block_kinds[-1] == "function":
                fstack.pop()["end"] = k
            close_block()
            k += 1
            continue
        if kind == "name" and val == "until":
            # until-condition still sees repeat-block locals -> close after the line
            flush_pending(force=True)
            e = k + 1
            depth = 0
            while e < n:
                if depth == 0 and newline_between(e - 1, e):
                    break
                if S[e][1] in ("(", "[", "{"):
                    depth += 1
                elif S[e][1] in (")", "]", "}"):
                    depth -= 1
                if S[e][0] == "name" and S[e - 1][1] not in (".", ":"):
                    d = lookup(S[e][1])
                    if d:
                        ref[e] = d
                e += 1
            close_block()
            k = e
            continue

        if val in ("(", "["):
            bdepth += 1
        elif val == "{":
            bdepth += 1
            brace_stack.append(bdepth)
        elif val in (")", "]"):
            bdepth -= 1
        elif val == "}":
            if brace_stack:
                brace_stack.pop()
            bdepth -= 1

        if kind == "name" and val not in KEYWORDS and prev not in (".", ":", "::"):
            nxt = S[k + 1][1] if k + 1 < n else ""
            is_key = brace_stack and brace_stack[-1] == bdepth and prev in ("{", ",", ";") and nxt == "="
            if not is_key:
                d = lookup(val)
                if d:
                    ref[k] = d
        k += 1

    # ---- usage-based hints for generic names (arg / tbl / fn / value) ----
    refs_of = {}
    for k2, d in ref.items():
        refs_of.setdefault(id(d), []).append(k2)
    PARAM_RULES = [
        ("Character", "player"), ("UserId", "player"), ("DisplayName", "player"),
        ("Health", "humanoid"), ("WalkSpeed", "humanoid"), ("TakeDamage", "humanoid"),
        ("HumanoidRootPart", "character"), ("KeyCode", "input"), ("UserInputType", "input"),
        ("Disconnect", "connection"), ("Position", "part"), ("CFrame", "part"),
        ("lower", "text"), ("upper", "text"), ("gsub", "text"), ("match", "text"),
        ("IsA", "instance"), ("FindFirstChild", "instance"), ("GetChildren", "instance"),
        ("Parent", "instance"), ("Destroy", "instance"),
    ]
    for d in decls:
        if d.hint and not re.match(r"(tbl|func|value|result|entry|str|num)\d*$", d.hint):
            continue
        rs = sorted(refs_of.get(id(d), []))
        if re.match(r"arg\d*$", d.old):
            feats = [S[r + 2][1] for r in rs if r + 2 < n and S[r + 1][1] in (".", ":")]
            for key, nm in PARAM_RULES:
                if key in feats:
                    d.hint = nm
                    break
        elif re.match(r"tbl\d+$", d.old):
            for r in rs:
                # X[#X + 1] = ...   -> list
                if r + 2 < n and S[r + 1][1] == "[" and S[r + 2][1] == "#":
                    d.hint = "list"
                    break
                # X[a.Name] = ...   -> byName
                if r + 5 < n and S[r + 1][1] == "[" and S[r + 3][1] == "." and S[r + 4][1] == "Name" \
                        and S[r + 5][1] == "]":
                    d.hint = "byName"
                    break
        elif re.match(r"fn\d*$", d.old):
            for r in rs:
                # A.B = fnN  /  B = fnN   -> b
                if r >= 2 and S[r - 1][1] == "=" and S[r - 2][0] == "name" \
                        and (r + 1 >= n or S[r + 1][1] not in ("(", ".", ":", "[")):
                    nm = _camel(S[r - 2][1])
                    if nm and not re.match(r"(fn|tbl|v|arg)\d*$", nm):
                        d.hint = nm
                        break

    EVENT_PARAMS = {
        "PlayerAdded": ["player"], "PlayerRemoving": ["player"], "CharacterAdded": ["character"],
        "CharacterRemoving": ["character"], "InputBegan": ["input", "gameProcessed"],
        "InputEnded": ["input", "gameProcessed"], "InputChanged": ["input", "gameProcessed"],
        "Touched": ["hit"], "TouchEnded": ["hit"], "ChildAdded": ["child"], "ChildRemoved": ["child"],
        "DescendantAdded": ["descendant"], "DescendantRemoving": ["descendant"],
        "Heartbeat": ["deltaTime"], "RenderStepped": ["deltaTime"], "Stepped": ["time", "deltaTime"],
        "Changed": ["newValue"], "OnChanged": ["newValue"], "Died": [], "Chatted": ["message"],
    }
    self_ok = {}
    scoped = []
    for rec in frecs:
        ps = rec["params"]
        if not ps:
            continue
        ctx = rec["ctx"]
        # Obsidian / Linoria / Fluent style: Callback = function(value)
        if len(ctx) >= 2 and ctx[-1] == "=" and ctx[-2] in ("Callback", "callback", "OnChanged", "Changed"):
            if re.match(r"arg\d*$", ps[0].old):
                scoped.append((ps[0], "value", rec))
            continue
        # X.Event:Connect(function(a, b))
        if len(ctx) >= 4 and ctx[-1] == "(" and ctx[-2] in ("Connect", "Once", "ConnectParallel", "OnChanged") \
                and ctx[-3] == ":":
            ev = ctx[-4]
            for d, nm in zip(ps, EVENT_PARAMS.get(ev, [])):
                if re.match(r"arg\d*$", d.old):
                    scoped.append((d, nm, rec))
            continue
        # A.B = function(arg, ...) where arg is used as an object -> self
        if len(ctx) >= 4 and ctx[-1] == "=" and ctx[-3] in (".", ":") and re.match(r"arg$", ps[0].old):
            body = [S[x][1] for x in range(rec["start"], min(rec["end"], n))]
            if "self" in body:
                continue
            rs = refs_of.get(id(ps[0]), [])
            STR_M = ("find", "sub", "match", "gmatch", "gsub", "lower", "upper", "len", "split", "rep", "byte", "format")
            dot = any(r + 2 < n and S[r + 1][1] == "." for r in rs)
            strm = any(r + 2 < n and S[r + 1][1] == ":" and S[r + 2][1] in STR_M for r in rs)
            fname = ctx[-2]
            method_call = any(S[x][1] == ":" and S[x + 1][1] == fname and S[x + 2][1] in ("(", "{", '"')
                              for x in range(n - 2))
            if method_call and not strm:
                scoped.append((ps[0], "self", rec))       # called as X:Name(...)
            elif strm and not dot:
                scoped.append((ps[0], "text", rec))
            elif dot and not strm:
                scoped.append((ps[0], "obj", rec))

    # scoped names: may repeat across sibling functions; never inside a function that
    # already uses that name (originally) or an ancestor function that got it
    given = []   # (name, start, end)
    for d, nm, rec in scoped:
        a, b = rec["start"], min(rec["end"], n)
        body = {S[x][1] for x in range(a, b) if S[x][0] == "name"}
        if nm in body or nm in KEYWORDS:
            continue
        if any(g == nm and ga <= a and b <= gb for g, ga, gb in given):
            continue
        given.append((nm, a, b))
        self_ok[id(d)] = nm

    # ---- pick new names ----
    taken = set(used) | {g for g, _, _ in given}
    for d in decls:
        if id(d) in self_ok and TARGET_RE.match(d.old):
            d.new = self_ok[id(d)]
            continue
        if not TARGET_RE.match(d.old) or not d.hint:
            continue
        if not re.match(r"v\d+$", d.old) and re.match(r"(tbl|func|value|result|entry|str|num|fn|arg)\d*$", d.hint):
            continue
        base = d.hint
        if id(d) in self_ok:
            d.new = self_ok[id(d)]
            continue
        new = base
        c = 2
        while new in taken or new in KEYWORDS or new in GLOBALS:
            new = "%s%d" % (base, c)
            c += 1
        taken.add(new)
        d.new = new

    for k, d in ref.items():
        if d.new and S[k][1] == d.old:
            S[k][1] = d.new
    return "".join(t[1] for t in toks)


def until_close_pending_check(_):
    return False


# ===================== SCATTERED WATERMARKS =====================
DISCORD = "https://discord.gg/x7YbZeezpm"
DISCORD_SHORT = "discord.gg/x7YbZeezpm"
ZW = "\u200b"


def _style(text, table):
    out = []
    for ch in text:
        if "A" <= ch <= "Z":
            out.append(chr(table[0] + ord(ch) - 65))
        elif "a" <= ch <= "z":
            out.append(chr(table[1] + ord(ch) - 97))
        else:
            out.append(ch)
    return "".join(out)


_FONTS = [
    lambda s: s,
    lambda s: _style(s, (0x1D400, 0x1D41A)),   # bold
    lambda s: _style(s, (0x1D5A0, 0x1D5BA)),   # sans
    lambda s: _style(s, (0x1D670, 0x1D68A)),   # monospace
    lambda s: _style(s, (0x1D5D4, 0x1D5EE)),   # sans bold
    lambda s: "".join(chr(0xFF21 + ord(c) - 65) if "A" <= c <= "Z" else
                      chr(0xFF41 + ord(c) - 97) if "a" <= c <= "z" else c for c in s),  # fullwidth
    lambda s: s.upper(),
    lambda s: ZW.join(s),                       # zero-width split (breaks plain search)
]

_TEMPLATES = [
    "-- {sl} | " + DISCORD,
    "-- " + DISCORD + " | {sl}",
    "--[[ {sl} :: " + DISCORD_SHORT + " ]]",
    "-- deobfuscated by {sl} -> " + DISCORD,
    "--[=[ {sl} ]=] -- " + DISCORD_SHORT,
    "-- join us: " + DISCORD,
    "-- {sl} // " + DISCORD_SHORT,
    "-- more leaks: " + DISCORD,
]
_NAMES = ["SL | Source Leak", "Source Leak", "SL", "Source Leak (SL)"]


def _mark(rng):
    font = rng.choice(_FONTS)
    tpl = rng.choice(_TEMPLATES)
    return tpl.replace("{sl}", font(rng.choice(_NAMES)))


def scatter_watermarks(text):
    """Insert a few watermark comments ONLY on blank lines between statements
    (never inside strings/comments), spaced by output size. Deterministic per output."""
    import random, hashlib
    toks = tokenize(text)
    if toks is None:
        return text
    lines_total = text.count("\n") + 1
    # ~1 per 300 lines, min 1, max 12
    want = max(1, min(12, lines_total // 300))
    if lines_total < 40:
        want = 0 if lines_total < 15 else 1
    # candidate positions: whitespace tokens that contain a blank line
    offs, pos = [], 0
    for kind, val in toks:
        if kind == "ws" and "\n\n" in val:
            cut = val.index("\n\n") + 1
            nxt = val[cut:].split("\n")
            indent = nxt[-1] if nxt else ""
            offs.append((pos + cut, indent))
        pos += len(val)
    if not offs or want == 0:
        return text
    rng = random.Random(hashlib.md5(text.encode("utf-8", "replace")).hexdigest())
    # spread evenly with jitter, skip first/last 5%
    n = len(offs)
    lo, hi = int(n * 0.05), max(int(n * 0.95), 1)
    picks = set()
    for i in range(want):
        a = lo + (hi - lo) * i // want
        b = lo + (hi - lo) * (i + 1) // want
        if b > a:
            picks.add(rng.randrange(a, b))
    for idx in sorted(picks, reverse=True):
        off, indent = offs[idx]
        text = text[:off] + indent + _mark(rng) + "\n" + text[off:]
    return text


def footer_watermark(text):
    import random, hashlib
    rng = random.Random(hashlib.sha1(text.encode("utf-8", "replace")).hexdigest())
    return text.rstrip("\n") + "\n\n" + _mark(rng) + "\n"


